11	const FORMAT_VERSION: u32 = 1;
12	const ALGORITHM: &str = "HMAC-SHA256";
13	/// Domain separator that also records the format version, so tags computed
14	/// by different versions of the encoding can never collide.
15	const DOMAIN_SEPARATOR: &[u8] = b"authnote-sign-v1";
