52	/// Run `verify --key <key>` feeding `input` to standard input.
53	fn run_verify(key: &str, input: &[u8]) -> Output {
54	    let mut cmd = authnote();
55	    cmd.arg("verify").arg("--key").arg(key);
56	    use std::io::Write;
57	    use std::process::Stdio;
58	    let mut child = cmd
59	        .stdin(Stdio::piped())
60	        .stdout(Stdio::piped())
61	        .stderr(Stdio::piped())
62	        .spawn()
63	        .expect("failed to spawn authnote");
64	    child
65	        .stdin
66	        .take()
67	        .unwrap()
68	        .write_all(input)
69	        .expect("failed to write record to stdin");
70	    child.wait_with_output().expect("failed to await authnote")
71	}
72	
73	/// Run `verify` with raw arguments and stdin (for option-error cases).
74	fn run_verify_raw(args: &[&str], input: &[u8]) -> Output {
75	    let mut cmd = authnote();
76	    cmd.arg("verify");
77	    for a in args {
78	        cmd.arg(a);
79	    }
80	    use std::io::Write;
81	    use std::process::Stdio;
82	    let mut child = cmd
83	        .stdin(Stdio::piped())
84	        .stdout(Stdio::piped())
85	        .stderr(Stdio::piped())
86	        .spawn()
87	        .expect("failed to spawn authnote");
88	    // Every caller here drives an error path that exits before reading stdin
89	    // (a malformed option), so the child may already be gone when we write; a
90	    // BrokenPipe then simply reflects that early exit and must not fail the
91	    // test. The outcome is still pinned by the exit code / stdout / stderr
92	    // assertions after reaping the child.
93	    if let Err(e) = child.stdin.take().unwrap().write_all(input) {
94	        assert_eq!(
95	            e.kind(),
96	            std::io::ErrorKind::BrokenPipe,
97	            "unexpected stdin write error: {e}"
98	        );
99	    }
100	    child.wait_with_output().expect("failed to await authnote")
101	}
