122	#[test]
123	fn verify_tolerates_reserialization_reordering_and_whitespace() {
124	    let key = "00112233445566778899aabbccddeeff";
125	    let record = sign_record_bytes(key, "kid-名字", "7", &["中文🙂", "x y"]);
126	
127	    // Parse, then emit pretty JSON with members in reverse order.
128	    let body = std::str::from_utf8(&record).unwrap().trim_end_matches('\n');
129	    let parsed = Json::parse(body);
130	    let obj = parsed.as_object();
131	    let mut reordered = String::from("{\n");
132	    for (i, (k, v)) in obj.iter().rev().enumerate() {
133	        if i > 0 {
134	            reordered.push_str(",\n");
135	        }
136	        reordered.push_str(&format!("  {k:?}: "));
137	        reordered.push_str(&json_value_to_text(v));
138	    }
139	    reordered.push_str("\n}");
140	    let padded = format!("  \t\n{reordered}\r\n  ");
141	
142	    let out = run_verify(key, padded.as_bytes());
143	    assert_eq!(out.status.code(), Some(0), "stderr={:?}", String::from_utf8_lossy(&out.stderr));
144	    assert_eq!(out.stdout, b"{\"valid\":true}\n");
145	    assert!(out.stderr.is_empty());
146	}
