148	/// Render a parsed Json back into compact JSON (test helper; records contain
149	/// only objects/arrays/strings/integers).
150	fn json_value_to_text(v: &Json) -> String {
151	    fn escape(s: &str) -> String {
152	        let mut out = String::from("\"");
153	        for c in s.chars() {
154	            match c {
155	                '"' => out.push_str("\\\""),
156	                '\\' => out.push_str("\\\\"),
157	                '\n' => out.push_str("\\n"),
158	                '\r' => out.push_str("\\r"),
159	                '\t' => out.push_str("\\t"),
160	                c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
161	                c => out.push(c),
162	            }
163	        }
164	        out.push('"');
165	        out
166	    }
167	    match v {
168	        Json::Str(s) => escape(s),
169	        Json::Num(n) => n.to_string(),
170	        Json::Arr(a) => format!(
171	            "[{}]",
172	            a.iter().map(json_value_to_text).collect::<Vec<_>>().join(",")
173	        ),
174	        Json::Obj(o) => format!(
175	            "{{{}}}",
176	            o.iter()
177	                .map(|(k, v)| format!("{}:{}", escape(k), json_value_to_text(v)))
178	                .collect::<Vec<_>>().join(",")
179	        ),
180	        other => panic!("unexpected value {other:?}"),
181	    }
182	}
