392	// ---------------------------------------------------------------------------
393	// Minimal JSON parser (objects, arrays, strings, integers, true/false/null).
394	// ---------------------------------------------------------------------------
395	
396	#[derive(Debug, Clone)]
397	enum Json {
398	    Null,
399	    // Retained for parser completeness; records carry no boolean values.
400	    #[allow(dead_code)]
401	    Bool(bool),
402	    Num(i64),
403	    Str(String),
404	    Arr(Vec<Json>),
405	    Obj(Vec<(String, Json)>),
406	}
407	
408	impl Json {
409	    fn parse(s: &str) -> Json {
410	        let mut p = Parser {
411	            chars: s.chars().collect(),
412	            pos: 0,
413	        };
414	        p.ws();
415	        let v = p.value();
416	        p.ws();
417	        assert_eq!(p.pos, p.chars.len(), "trailing data after JSON record: {s}");
418	        v
419	    }
420	
421	    fn as_str(&self) -> &str {
422	        match self {
423	            Json::Str(s) => s,
424	            other => panic!("expected JSON string, got {other:?}"),
425	        }
426	    }
427	
428	    fn as_i64(&self) -> i64 {
429	        match self {
430	            Json::Num(n) => *n,
431	            other => panic!("expected JSON number, got {other:?}"),
432	        }
433	    }
434	
435	    fn as_array(&self) -> &[Json] {
436	        match self {
437	            Json::Arr(a) => a,
438	            other => panic!("expected JSON array, got {other:?}"),
439	        }
440	    }
441	
442	    fn as_object(&self) -> &[(String, Json)] {
443	        match self {
444	            Json::Obj(o) => o,
445	            other => panic!("expected JSON object, got {other:?}"),
446	        }
447	    }
448	
449	    fn get(&self, key: &str) -> &Json {
450	        let obj = self.as_object();
451	        let idx = obj
452	            .iter()
453	            .position(|(k, _)| k == key)
454	            .unwrap_or_else(|| panic!("missing key {key:?} in {self:?}"));
455	        &obj[idx].1
456	    }
457	
458	    /// Every string value anywhere in the document.
459	    fn strings(&self, out: &mut Vec<String>) {
460	        match self {
461	            Json::Str(s) => out.push(s.clone()),
462	            Json::Arr(a) => a.iter().for_each(|v| v.strings(out)),
463	            Json::Obj(o) => o.iter().for_each(|(_, v)| v.strings(out)),
464	            Json::Null | Json::Bool(_) | Json::Num(_) => {}
465	        }
466	    }
467	}
468	
469	struct Parser {
470	    chars: Vec<char>,
471	    pos: usize,
472	}
473	
474	impl Parser {
475	    fn ws(&mut self) {
476	        while self.pos < self.chars.len() && self.chars[self.pos].is_whitespace() {
477	            self.pos += 1;
478	        }
479	    }
480	
481	    fn bump(&mut self) -> char {
482	        assert!(self.pos < self.chars.len(), "unexpected end of JSON");
483	        let c = self.chars[self.pos];
484	        self.pos += 1;
485	        c
486	    }
487	
488	    fn expect(&mut self, want: char) {
489	        assert!(self.pos < self.chars.len(), "expected {want:?}, found end of JSON");
490	        let got = self.chars[self.pos];
491	        assert_eq!(got, want, "expected {want:?} at position {}", self.pos);
492	        self.pos += 1;
493	    }
494	
495	    fn value(&mut self) -> Json {
496	        self.ws();
497	        assert!(self.pos < self.chars.len(), "unexpected end of JSON");
498	        match self.chars[self.pos] {
499	            '{' => self.object(),
500	            '[' => self.array(),
501	            '"' => Json::Str(self.string()),
502	            't' | 'f' => self.boolean(),
503	            'n' => self.null(),
504	            c if c == '-' || c.is_ascii_digit() => self.number(),
505	            c => panic!("unexpected character {c:?} in JSON"),
506	        }
507	    }
508	
509	    fn object(&mut self) -> Json {
510	        self.expect('{');
511	        let mut entries = Vec::new();
512	        self.ws();
513	        if self.chars[self.pos] == '}' {
514	            self.pos += 1;
515	            return Json::Obj(entries);
516	        }
517	        loop {
518	            self.ws();
519	            let key = self.string();
520	            self.ws();
521	            self.expect(':');
522	            let val = self.value();
523	            entries.push((key, val));
524	            self.ws();
525	            match self.bump() {
526	                ',' => continue,
527	                '}' => break,
528	                c => panic!("bad object separator {c:?}"),
529	            }
530	        }
531	        Json::Obj(entries)
532	    }
533	
534	    fn array(&mut self) -> Json {
535	        self.expect('[');
536	        let mut items = Vec::new();
537	        self.ws();
538	        if self.chars[self.pos] == ']' {
539	            self.pos += 1;
540	            return Json::Arr(items);
541	        }
542	        loop {
543	            items.push(self.value());
544	            self.ws();
545	            match self.bump() {
546	                ',' => continue,
547	                ']' => break,
548	                c => panic!("bad array separator {c:?}"),
549	            }
550	        }
551	        Json::Arr(items)
552	    }
553	
554	    fn string(&mut self) -> String {
555	        self.expect('"');
556	        let mut out = String::new();
557	        loop {
558	            match self.bump() {
559	                '"' => break,
560	                '\\' => match self.bump() {
561	                    '"' => out.push('"'),
562	                    '\\' => out.push('\\'),
563	                    '/' => out.push('/'),
564	                    'b' => out.push('\u{0008}'),
565	                    'f' => out.push('\u{000c}'),
566	                    'n' => out.push('\n'),
567	                    'r' => out.push('\r'),
568	                    't' => out.push('\t'),
569	                    'u' => {
570	                        let hi = self.hex4();
571	                        let c = if (0xD800..=0xDBFF).contains(&hi) {
572	                            assert_eq!(self.bump(), '\\');
573	                            assert_eq!(self.bump(), 'u');
574	                            let lo = self.hex4();
575	                            assert!(
576	                                (0xDC00..=0xDFFF).contains(&lo),
577	                                "bad low surrogate {lo:x}"
578	                            );
579	                            char::from_u32(0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00))
580	                                .expect("bad surrogate pair")
581	                        } else {
582	                            char::from_u32(hi).expect("bad unicode escape")
583	                        };
584	                        out.push(c);
585	                    }
586	                    c => panic!("bad escape \\{c}"),
587	                },
588	                // Raw control bytes must not appear unescaped in JSON text.
589	                c if (c as u32) < 0x20 => panic!("unescaped control character {c:?} in JSON"),
590	                c => out.push(c),
591	            }
592	        }
593	        out
594	    }
595	
596	    fn hex4(&mut self) -> u32 {
597	        let mut v = 0u32;
598	        for _ in 0..4 {
599	            let c = self.bump();
600	            v = v * 16 + c.to_digit(16).unwrap_or_else(|| panic!("bad hex digit {c:?}"));
601	        }
602	        v
603	    }
604	
605	    fn number(&mut self) -> Json {
606	        let start = self.pos;
607	        if self.chars[self.pos] == '-' {
608	            self.pos += 1;
609	        }
610	        while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
611	            self.pos += 1;
612	        }
613	        let text: String = self.chars[start..self.pos].iter().collect();
614	        Json::Num(text.parse().unwrap_or_else(|_| panic!("bad number {text}")))
615	    }
616	
617	    fn boolean(&mut self) -> Json {
618	        if self.chars[self.pos] == 't' {
619	            for want in "true".chars() {
620	                self.expect(want);
621	            }
622	            Json::Bool(true)
623	        } else {
624	            for want in "false".chars() {
625	                self.expect(want);
626	            }
627	            Json::Bool(false)
628	        }
629	    }
630	
631	    fn null(&mut self) -> Json {
632	        for want in "null".chars() {
633	            self.expect(want);
634	        }
635	        Json::Null
636	    }
637	}
