717	/// Successful invocation: exit code 0, empty stderr, one valid record whose
718	/// fields/key-id/version match the inputs and whose tag equals the golden
719	/// value computed independently of this implementation.
720	fn expect_signed_record(
721	    label: &str,
722	    key: &str,
723	    key_id: &str,
724	    version: &str,
725	    fields: &[&str],
726	    golden_tag: &str,
727	) -> Record {
728	    let out = run_sign(key, key_id, version, fields);
729	    assert_eq!(
730	        out.status.code(),
731	        Some(0),
732	        "{label}: expected exit 0, got {:?}, stderr={:?}",
733	        out.status.code(),
734	        String::from_utf8_lossy(&out.stderr)
735	    );
736	    assert!(
737	        out.stderr.is_empty(),
738	        "{label}: stderr must be empty, got {:?}",
739	        String::from_utf8_lossy(&out.stderr)
740	    );
741	
742	    let rec = parse_single_record(&out.stdout);
743	    assert_eq!(rec.tag, golden_tag, "{label}: tag mismatch");
744	    assert_eq!(rec.key_id, key_id, "{label}: key_id mismatch");
745	    assert_eq!(
746	        rec.key_version,
747	        version.parse::<i64>().unwrap(),
748	        "{label}: key_version mismatch"
749	    );
750	    assert_eq!(
751	        rec.fields,
752	        fields.iter().map(|s| s.to_string()).collect::<Vec<_>>(),
753	        "{label}: parsed fields must be character-identical to the inputs"
754	    );
755	
756	    // The raw key is used only for the MAC: it must never appear as a value
757	    // anywhere in the record (compared as a whole string, not a substring, so
758	    // short keys cannot clash with random fragments of the 64-char tag).
759	    let needle = key.to_lowercase();
760	    let mut strings = Vec::new();
761	    rec.raw.strings(&mut strings);
762	    assert!(
763	        strings.iter().all(|s| s.to_lowercase() != needle),
764	        "{label}: raw key material must not be part of the record"
765	    );
766	    rec
767	}
