912	    assert_eq!(out2.status.code(), Some(0));
913	    assert!(out1.stderr.is_empty() && out2.stderr.is_empty());
914	    (
915	        parse_single_record(&out1.stdout),
916	        parse_single_record(&out2.stdout),
917	        out1.stdout,
918	        out2.stdout,
919	    )
920	}
