1475	    let tag64 = "0".repeat(64);
1476	    let record = |fields_json: &str| -> String {
1477	        format!(
1478	            r#"{{"format":1,"algorithm":"HMAC-SHA256","key_id":"{EXT2_KID}","key_version":1,{fields_json},"tag":"{tag64}"}}"#
1479	        )
1480	    };
1481	
1482	    // Truncated \u in the middle of a string, and cut off exactly at the end
1483	    // of the input (no closing quote either).
1484	    let truncated_mid = record(r#""fields":["\u000"]"#);
1485	    let truncated_at_eof =
1486	        r#"{"format":1,"algorithm":"HMAC-SHA256","key_id":"外部记录","key_version":1,"fields":["\u00"#.to_string();
1487	    // Surrogate forms that never combine into one legal character.
1488	    let lone_high = record(r#""fields":["\ud83d"]"#);
1489	    let low_out_of_range = record(r#""fields":["\ud83dA"]"#);
1490	    let high_then_high = record(r#""fields":["\ud83d\ud83d"]"#);
1491	    let lone_low = record(r#""fields":["\ude42"]"#);
1492	    let bad_hex_digit = record(r#""fields":["\u00g0"]"#);
1493	
1494	    for (label, rec) in [
1495	        ("truncated escape", truncated_mid.as_str()),
1496	        ("truncated escape at EOF", truncated_at_eof.as_str()),
1497	        ("lone high surrogate", lone_high.as_str()),
1498	        ("low surrogate out of range", low_out_of_range.as_str()),
1499	        ("high surrogate paired with high", high_then_high.as_str()),
1500	        ("lone low surrogate", lone_low.as_str()),
1501	        ("non-hex digit in escape", bad_hex_digit.as_str()),
1502	    ] {
1503	        let stderr = expect_verify_invalid(rec.as_bytes(), &["--key", EXT2_KEY]);
1504	        // Error text explains the formatting problem but never quotes the key,
1505	        // record content, or the rejected escape's digits/value.
1506	        assert!(!stderr.contains(EXT2_KEY), "{label}: stderr echoed the key: {stderr}");
1507	        assert!(
1508	            !stderr.contains(EXT2_KID),
1509	            "{label}: stderr echoed record content: {stderr}"
1510	        );
