1512	            !stderr.as_bytes().contains(&0),
1513	            "{label}: stderr echoed a NUL byte: {stderr:?}"
1514	        );
1515	        assert!(
1516	            !stderr.contains("d83d") && !stderr.contains("de42"),
1517	            "{label}: stderr echoed the rejected escape value: {stderr}"
1518	        );
1519	    }
1520	
1521	    // A raw, unescaped NUL byte in the JSON text is corrupt input too: it may
1522	    // not be accepted as the escaped NUL and must not cut the string short.
1523	    let mut raw_nul = record(r#""fields":["前@后"]"#).into_bytes();
1524	    let at_pos = raw_nul.iter().position(|&b| b == b'@').unwrap();
1525	    raw_nul[at_pos] = 0;
1526	    let stderr = expect_verify_invalid(&raw_nul, &["--key", EXT2_KEY]);
1527	    assert!(!stderr.contains(EXT2_KEY), "stderr echoed the key: {stderr}");
1528	    assert!(!stderr.as_bytes().contains(&0), "stderr echoed the NUL: {stderr:?}");
1529	}
