1542	/// Overwrite the spelling of one member name inside a compact signed record.
1543	/// `spelling` is the raw JSON text of the replacement name (without the
1544	/// quotes), so escape sequences can be supplied exactly as they appear on
1545	/// the wire.
1546	fn respell_member(record: &str, canonical: &str, spelling: &str) -> String {
1547	    let needle = format!("\"{canonical}\":");
